import { useState, createContext, useContext } from "react";

// Compound components: Tabs + Tabs.Tab + Tabs.Panel chia sẻ state qua Context
const TabsCtx = createContext(null);

function Tabs({ children, defaultValue }) {
  const [value, setValue] = useState(defaultValue);
  return <TabsCtx.Provider value={{ value, setValue }}><div>{children}</div></TabsCtx.Provider>;
}
Tabs.Tab = function Tab({ value, children }) {
  const { value: cur, setValue } = useContext(TabsCtx);
  return <button aria-selected={cur === value} onClick={() => setValue(value)}>{children}</button>;
};
Tabs.Panel = function Panel({ value, children }) {
  const { value: cur } = useContext(TabsCtx);
  return cur === value ? <div>{children}</div> : null;
};

export default function App() {
  return (
    <Tabs defaultValue="a">
      <Tabs.Tab value="a">Một</Tabs.Tab>
      <Tabs.Tab value="b">Hai</Tabs.Tab>
      <Tabs.Panel value="a"><p id="pa">Nội dung một</p></Tabs.Panel>
      <Tabs.Panel value="b"><p id="pb">Nội dung hai</p></Tabs.Panel>
    </Tabs>
  );
}

